contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 burnAmount) public {
        address owner = c.owner();
        uint256 beforeBalance = c.balanceOf(owner);
        uint256 beforeSupply = c.totalSupply();
        require(burnAmount <= beforeBalance);

        bool reverted;
        try c.burn(burnAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterBalance = c.balanceOf(owner);
        uint256 afterSupply = c.totalSupply();

        if (reverted) {
            assert(afterBalance == beforeBalance && afterSupply == beforeSupply);
        } else {
            assert(!reverted && afterBalance == beforeBalance - burnAmount && afterSupply == beforeSupply - burnAmount);
        }
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address target, bool freeze) public {
        require(target != address(0), "target must not be zero");
        require(target != address(this), "target must not be test contract");

        // read pre-state for target and another key to ensure only target is modified
        address other = address(0xdead);
        bool beforeTarget = c.frozenAccount(target);
        bool beforeOther = c.frozenAccount(other);

        // the deciding call
        c.freezeAccount(target, freeze);

        // read post-state
        bool afterTarget = c.frozenAccount(target);
        bool afterOther = c.frozenAccount(other);

        assert(afterTarget == freeze && afterOther == beforeOther);
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address target, bool freeze) public {
        require(target != address(0), "target must not be zero");

        // read before state of target and caller
        bool beforeTarget = c.frozenAccount(target);
        bool beforeCaller = c.frozenAccount(msg.sender);

        // deciding call
        c.freezeAccount(target, freeze);

        // read after state
        bool afterTarget = c.frozenAccount(target);
        bool afterCaller = c.frozenAccount(msg.sender);

        if (target == msg.sender) {
            assert(afterTarget == freeze && afterCaller == freeze);
        } else {
            assert(afterTarget == freeze && afterCaller == beforeCaller);
        }
    }
}

